local S = {}

S.guides = {
    { name = 'Succor to the Sidhe', group = 'Custom', desc = 'A repeatable quest from Callisto in Grauberg [S] that adds random augments to one of the 20 Fay-line weapons. Source: https://scythe-bbq.pages.dev/fay-weapons.html', steps = { { title = 'Get a Fay-line weapon', note = '• Obtain one of the 20 eligible weapons (Fay, Erlking, Dweomer and Ogre lines from WotG Campaign / Allied Notes shops and retail quests), one per job.\n• Examples: Oberon\'s Rapier (RDM), Erlking\'s Sword (PLD), Rindomaru (SAM), Dweomer Maul (WHM), Fay Lance (DRG).\n• Confirm eligibility with /checkparam on the weapon.' }, { title = 'Trade to Callisto', note = '• Go to Callisto in Grauberg [S] at (-102, 538), close to the reive area.\n• Trade the weapon; she names a Shadowreign zone to visit.' }, { title = 'Kill the Pixie NM', note = '• Defeat that zone\'s Pixie NM, an open-world spawn rather than an instance.\n• The zone you choose decides the augment pool.' }, { title = 'Collect the augments', note = '• Go back to Callisto; she offers the weapon with as many as two random augments drawn from the chosen zone\'s list (e.g. STR, DEX, Accuracy, Attack, Store TP, Double Attack, WSD, MAB, Cure Potency).' }, { title = 'Accept or reroll', note = '• Decline the roll and repeat the run if you want a different result.\n• Each weapon gets 5 reroll attempts; after that the augments are fixed.' } } },
    { name = 'Dynamis Divergence entry', group = 'Custom', desc = 'Entry steps for the instanced Dynamis Divergence zones via Aurix in Ru\'Lude Gardens and the Enigmatic Footprints NPCs. Source: https://scythe-bbq.pages.dev/dynamis-divergence.html', steps = { { title = 'Finish Rhapsodies of Vana\'diel', note = '• Complete A Rhapsody for the Ages, the last RoV mission; mission-skip completion markers or the Scintillating Rhapsody key item also qualify.' }, { title = 'Get a currency piece', note = '• Bring one One Hundred Byne Bill, Montiont Silverpiece, or Lungo-Nango Jadeshell.' }, { title = 'Trade to Aurix', note = '• Trade the currency to Aurix in Ru\'Lude Gardens to receive the Empty Hourglass key item.' }, { title = 'Buy a Prismatic Hourglass', note = '• Pay 50,000 gil to an Enigmatic Footprints NPC in Windurst Walls, Bastok Mines, Southern San d\'Oria, or Ru\'Lude Gardens.' }, { title = 'Enter', note = '• Speak to the same Enigmatic Footprints NPC and choose a Divergence zone; your alliance goes in with you.\n• Lockout: one run per player per day, 24 hours counted from midnight.\n• All four Divergence zones are enabled; alliance size suggested for the nation zones, a full party for Jeuno.' } } },
    { name = 'Sortie entry', group = 'Custom', desc = 'How to begin a 60-minute Sortie run in Outer Ra\'Kaznar [U1] using Ruspix in Leafallia and the Diaphanous Transposer in Kamihr Drifts. Source: https://scythe-bbq.pages.dev/sortie.html', steps = { { title = 'Get the plate', note = '• Talk to Ruspix in Leafallia to receive a Shiny Ra\'Kaznarian plate.' }, { title = 'Use the Transposer', note = '• Go to Frontier Bivouac #4 in Kamihr Drifts and use the Diaphanous Transposer.' }, { title = 'Enter the instance', note = '• The plate turns dull once the run begins.\n• Time limit 60 minutes; sectors A-H, each with a roaming minor NM.\n• Major NMs open via sector gadgets; Aminon is the final boss after the basement fragment chain.\n• Named foes: 8 minor NMs, 8 major NMs, Aminon.' }, { title = 'Spend rewards', note = '• Collect shards, sheets, fragments and metals during the run.\n• Rewards include Gallimaufry, Ra\'Kaz. Sapphires and Ra\'Kaz. Starstones.\n• Spend them with Ruspix for Empyrean armor +2 and +3 upgrades.' } } },
    { name = 'Base REMA weapon (!rema shop)', group = 'Custom', desc = 'Requirements for buying a base Relic, Mythic, Empyrean or Ergon weapon with the !rema command for 5,000,000 gil each. Source: https://scythe-bbq.pages.dev/weapon-progression.html', steps = { { title = 'Rank 10', note = '• Reach rank 10 in any starting nation; the rank of your current nation is what is checked.' }, { title = 'Kill the 10 gate HNMs', note = '• Defeat each of the 10 gate HNMs once; credit is per character, permanent, and shared with alliance members in the zone at the kill.' }, { title = 'Save gil', note = '• Have 5,000,000 gil for every weapon you plan to buy.' }, { title = 'Use !rema', note = '• Type !rema; if qualified, the shop lists base REMA weapons for your current main job.\n• If not, it shows your rank and remaining kills.' } } },
    { name = 'Starting the NM Hunt', group = 'Custom', desc = 'How to start Scythe\'s hunt of 475 regular NMs across 145 zones, plus 25 elite encounters, via the NM Hunts Master in Celennia Memorial Library. Source: https://scythe-bbq.pages.dev/nm-hunt.html', steps = { { title = 'Reach 99', note = '• Get a job to level 99; regular hunt NMs are level 80 with 2x HP/MP and combat stats.' }, { title = 'Enter the library', note = '• In Eastern Adoulin, speak to Eppel-Treppel to enter Celennia Memorial Library.' }, { title = 'Talk to the Hunts Master', note = '• Use the NM Hunts Master to check progress, take a daily, hard, or weekly bounty, and see remaining targets.\n• !huntstatus shows progress from anywhere.' }, { title = 'Hunt', note = '• Choose a zone, go to the NM\'s grid square, and kill it.\n• Kills earn Scyld and count toward unique-kill milestones (Mog Kupons for job armor, later a free REMA weapon).' }, { title = 'Spend Scyld', note = '• Use the NM Hunt shop NPC beside the Hunts Master for cosmetics and milestone Kupons.\n• Clearing all 475 unlocks the Elite Hunts: 24 field elites and a final battlefield boss.' } } },
    { name = 'Starting the Elite Hunts', group = 'Custom', desc = 'How to begin the 25 Elite Hunt encounters once all 475 regular hunt NMs are dead, via the NM Hunts Master in Celennia Memorial Library. Source: https://scythe-bbq.pages.dev/elite-hunts.html', steps = { { title = 'Clear the 475', note = '• Kill all 475 regular hunt NMs (per character); check eligibility with !huntstatus.' }, { title = 'Open the Elite board', note = '• Talk to the NM Hunts Master; eligible characters see an Elite board option.' }, { title = 'Begin at Tier 4', note = '• Pick an Elemental Seal (e.g. Fire Seal at Cape Teriggan), kill the matching elemental family to raise the counter, then wait for the required weather.' }, { title = 'Climb the tiers in order', note = '• Order is fixed: Seals (Tier 4) → Champions (Tier 3) → Specials (Tier 2) → Supremes (Tier 1) → Absolute Virtue.\n• Each elite also has spawn conditions: Vana\'diel day, weather, moon phase, titles, or zone kill counters.\n• Seal and Gyve mean the same 8 elemental Tier-4 bosses; a Vana\'diel day is about 58 real minutes; the moon cycle is 84 days (check /clock); some spawns need a zone Reive state.' }, { title = 'Rewards and tuning', note = '• 250 Scyld per elite kill.\n• Elites are level 99 with 15x HP/MP and 5x combat stats, tuned for 6-player parties; some Tier 4 Seals can be soloed with strong setups.' } } },
    { name = 'Spending Scyld', group = 'Custom', desc = 'How to spend Scyld, the hunt currency, at the NM Hunt shop in Celennia Memorial Library. Source: https://scythe-bbq.pages.dev/scyld-shop.html', steps = { { title = 'Earn Scyld', note = '• 25 per regular hunt NM (every party member gets it), 250 per elite, plus 50-500 bonus for completing a daily, hard, or weekly bounty.' }, { title = 'Reach the shop', note = '• Enter Celennia Memorial Library through Eppel-Treppel in Eastern Adoulin.\n• Talk to the NM Hunt shop NPC beside the Hunts Master.' }, { title = 'Buy', note = '• Choose from three cosmetic pages (monster suits, event gear, anniversary sets) or claim a milestone Kupon once you meet its unique-kill threshold.' }, { title = 'Redeem Kupons', note = '• Trade a Kupon to a Mog Bonanza Moogle in any starting city to receive the weapon, armor piece, or seal.' } } },
    { name = 'Joining a FATE', group = 'Custom', desc = 'How to take part in one of Scythe\'s 88 open-world FATE events spread over 44 zones (level caps 12-99). Source: https://scythe-bbq.pages.dev/fate.html', steps = { { title = 'Go to a FATE zone', note = '• A FATE may spawn at each in-game hour change if the zone\'s cooldown has passed; one FATE per zone at a time.\n• Cooldowns: 40 minutes for annihilation FATEs, 60-120 minutes for notorious ones.' }, { title = 'Watch for the announcement', note = '• A [FATE] message in zone chat gives the event name, landmark or map grid, and time limit.' }, { title = 'Sync', note = '• Talk to the FATE Sync NPC in the middle of the event area; higher-level players are synced down to the zone cap.' }, { title = 'Engage', note = '• FATE mobs can\'t be targeted until a synced player engages; then they activate for all.' }, { title = 'Earn contribution', note = '• Both kills and time spent inside the radius (55-85 yalms, depending on the event) raise your score.' }, { title = 'Rewards', note = '• Rewards are handed out automatically by individual score; no looting or party needed.\n• Currency is Luminas (charvar [FATE]Luminas); Gold contribution can give up to 20% of your next level in EXP.\n• Solo is possible; a party is advised in Abyssea and Escha.' } } },
    { name = 'Joining a Siege raid', group = 'Custom', desc = 'How to join a server-wide Siege raid of 5 waves, currently the main live source of Exemplar Points for Master Levels. Source: https://scythe-bbq.pages.dev/siege.html', steps = { { title = 'Wait for the call', note = '• All online players get a linkshell message and on-screen notice naming the siege zone.' }, { title = 'Travel', note = '• Use !headto to reach the closest city, or a home point or Warp; the zone remains open for the whole event.' }, { title = 'Fight', note = '• Join any party or go solo; EP is counted per player, and Trusts are scaled up for sieges.' }, { title = 'Clear the waves', note = '• Waves 1-3 are the approach, wave 4 a gauntlet, wave 5 a phased boss; difficulty rises each wave.' }, { title = 'Rewards', note = '• EP is paid by contribution, with a minimum for anyone present at the end.' } } },
    { name = 'Synergy crafting', group = 'Custom', desc = 'How to craft with a Synergy Engineer and Synergy Furnace, available in 17 zones with no guild rank or unlock quest. Source: https://scythe-bbq.pages.dev/synergy.html', steps = { { title = 'Find the NPC and furnace', note = '• Locate a Synergy Engineer (teaches recipes, turns crystals into fewell) and a Synergy Furnace (the crafting device) in any of the 17 zones, including every capital.' }, { title = 'Choose a recipe', note = '• The Engineer lists the needed materials: elemental fewell plus the recipe\'s catalysts.' }, { title = 'Run the session', note = '• At the Furnace, keep the elemental flow balanced; high instability can destroy the materials.' }, { title = 'Level the skill', note = '• Synergy skill rises with use; higher skill gives steadier sessions and better HQ rates.' }, { title = 'Collect results', note = '• Success yields items; HQ gives the premium version (e.g. +1 monster suits, HQ event gear).\n• Synergy makes items unavailable elsewhere: monster suits, HQ event gear, some weapons, cosmetics.' } } },
    { name = 'Upgrading a Trust', group = 'Custom', desc = 'How to take any of the 122 Trusts through its three upgrade tiers. Source: https://scythe-bbq.pages.dev/trusts.html', steps = { { title = 'Earn Trust currency', note = '• Convert points at the Trust Stone Exchange NPC in Ru\'Lude Gardens; currencies are stored as character variables, not items.\n• 5 Merit Points = 1 Trust Stone (Tier I).\n• 10 Merit Points or 100 Job Points = 1 Trust Gem (Tier II).\n• 500 Job Points = 1 Trust Jewel (Tier III).' }, { title = 'Find the upgrade NPC', note = '• Each Trust has its own NPC using its model, found in the starting nations, Jeuno, Adoulin, and some other zones (e.g. Zeid in Bastok Mines, Shantotto in Windurst Walls, Maat in Ru\'Lude Gardens).' }, { title = 'Check the requirements', note = '• Each tier needs the right stones, gems, or jewels, a specific trade item, and sometimes a gate such as nation rank, job level, fame, kill count, or crafting skill.' }, { title = 'Trade', note = '• Trade the item; the NPC takes it plus the currency and raises the tier, which applies next time you summon the Trust.' } } },
    { name = 'Learning Blue Magic', group = 'Custom', desc = 'How a Blue Mage picks up spells from monster abilities on Scythe (196 teachable spells across 70+ mob families). Source: https://scythe-bbq.pages.dev/blue-magic.html', steps = { { title = 'Main job BLU', note = '• BLU must be your main job; spells cannot be learned as a subjob.' }, { title = 'Find the mob', note = '• Hunt a mob from the family that teaches the spell, in any zone with that family (retail locations).' }, { title = 'Take the TP move', note = '• Let the mob use its ability on you; it must resolve against you, though a resist or miss still counts.' }, { title = 'Trigger the check', note = '• Kill the mob or leave the zone; on success the log shows "You learned [spell]!".\n• Learning is a chance and may take several attempts.' }, { title = 'Set the spell', note = '• Equip it via Magic → Set Spells; each spell uses Set Points (base 20, raised by gear).' } } },
    { name = 'Your First Hour', group = 'Custom', desc = 'An ordered checklist for a new character\'s first hour on Scythe. Source: https://scythe-bbq.pages.dev/guides.html', steps = { { title = 'Welcome items', note = '• First login gives all maps, a server linkpearl, and a welcome packet; keep the linkpearl for event and siege announcements.' }, { title = 'Turn on !buff', note = '• Type !buff for scaling Regen/Refresh/Regain and +200% EXP below 99; at 99 it becomes +200% Capacity Points.\n• Type !buff again to switch it off.' }, { title = 'Go to the hub', note = '• Type !cc to warp to Chocobo Circuit.\n• It has the auction house, all 9 guild material vendors (no rank needed), a crystal vendor, a crystal storage moogle, the Advanced Support NPC (15-minute Imagery buff), and the mission-item shop (!shop 1 or !shop 2).' }, { title = 'Claim Login Points', note = '• Talk to the Greeter Moogle in Port San d\'Oria, Port Bastok, or Port Windurst.\n• 500 points for the first login each Earth day, 100 for later logins; spend on Trust Ciphers, mounts, rings, and upgrade items.' }, { title = 'Choose a job', note = '• All 22 jobs, including advanced ones, are open at creation without unlock quests.\n• Subjob levels alongside the main (99/99); Trusts are enabled.' }, { title = 'Level', note = '• EXP is 4x, no death penalty, Fields/Grounds of Valor manuals enabled, and Records of Eminence award Sparks.' }, { title = 'Begin hunting', note = '• With a ready 99, enter Celennia Memorial Library via Eppel-Treppel in Eastern Adoulin and talk to the NM Hunts Master.\n• The 475-NM chain leads to Elite Hunts, milestone Kupons, and a free REMA weapon at 500 unique kills.' } } },
    { name = 'Path A — Never Played FFXI', group = 'Custom', desc = 'The site\'s suggested progression for players new to FFXI. Source: https://scythe-bbq.pages.dev/guides.html', steps = { { title = 'Step 1', note = '• Start as Red Mage, Beastmaster, or Blue Mage, which all solo well, and add Trusts.' }, { title = 'Step 2', note = '• Level 1-50 around your home nation with Fields of Valor manuals, !buff, and 4x EXP.' }, { title = 'Step 3', note = '• At 50, finish Maat\'s limit-break quests, then level to 75 through Abyssea custom pops (direct item-trade ??? pops, no KI chain, some level 125 boosted variants).' }, { title = 'Step 4', note = '• Go from 75 to 99 using Records of Eminence objectives and Abyssea parties.' }, { title = 'Step 5', note = '• At 99, try a first hunt NM in an easy zone such as East Ronfaure or Jugner Forest to earn Scyld.' }, { title = 'Step 6', note = '• Play the expansion missions whenever you like; most grant permanent stat rewards and key items.' } } },
    { name = 'Path B — Returning Retail Player', group = 'Custom', desc = 'The site\'s suggested progression for players returning from retail. Source: https://scythe-bbq.pages.dev/guides.html', steps = { { title = 'Step 1', note = '• Use !buff, 4x EXP, and 5x skill-up chance and gain to get an old main to 99 with capped skills quickly.' }, { title = 'Step 2', note = '• Get base job armor with !af, !relic, and !empy.\n• Buy a base REMA weapon with !rema (requires nation rank 10, 10 HNM kills, 5M gil); upgrades come from Scyld shop Kupons.' }, { title = 'Step 3', note = '• Start hunt NMs: kill credit holds in groups, the respawn window is a steady 9-11 minutes with no fixed ToD, and the Hunts Master offers daily and weekly bounties for bonus Scyld.' }, { title = 'Step 4', note = '• Upgrade relics; relic weapon skills use fTP 5.0/9.0/13.0 and multi-hit fTP replication.' }, { title = 'Step 5', note = '• Long term, reach 500 unique NM kills for Kupon W-RMEA (a free REMA weapon of your choice) and raise ML through sieges and, later, the Colosseum.' } } },
    { name = 'Path C — Solo Player', group = 'Custom', desc = 'The site\'s suggested progression for solo players. Source: https://scythe-bbq.pages.dev/guides.html', steps = { { title = 'Step 1', note = '• Buy Trust Ciphers from the Greeter Moogle at 100 Login Points each; aim for a healer, tank, nuker, and buffer.' }, { title = 'Step 2', note = '• Level 1-99 as in Path A; Trusts scale with you, and BST or BLU pair well with a small Trust group.' }, { title = 'Step 3', note = '• Hunt NMs with a Trust party and good gear, starting in zones that have 3 NMs; track kills with !huntstatus.' }, { title = 'Step 4', note = '• For ML, attend sieges for EP; the planned Colosseum Solo mode will have 0.5x boss HP and 2.5x EP.' }, { title = 'Step 5', note = '• Some Tier 4 Elemental Seal elites can be soloed with good gear and buffs.' }, { title = 'Step 6', note = '• As a side activity, run Fay weapon augments: one Pixie NM per run in a Shadowreign zone.' } } },
    { name = 'Path D — Endgame Hunter', group = 'Custom', desc = 'The site\'s suggested progression for endgame hunters, plus a list of key NPCs. Source: https://scythe-bbq.pages.dev/guides.html', steps = { { title = 'Step 1', note = '• Level a main DD (WAR, DRK, SAM, or MNK) and a support (WHM or SCH) to 99; upgrade job armor with Scyld shop Kupons.' }, { title = 'Step 2', note = '• Sweep the regular NM list zone by zone, tracking with !huntstatus.\n• Milestones: 50 = Golden Bomb Mount, 100 = Kupon I-Skill, 200 = Kupon I-Seal (Abdhaljs for +2/+3 armor), 400 = Kupon I-RME (300 REMA upgrade materials).' }, { title = 'Step 3', note = '• At 400 kills, use I-RME to complete a REMA upgrade before attempting elites.' }, { title = 'Step 4', note = '• At 475 unique kills, start Elite Hunts with Tier 4 Elemental Seals (zone kill counts plus weather).' }, { title = 'Step 5', note = '• Clear every field elite to spawn Absolute Virtue; killing it resets the field-elite chain.' }, { title = 'Step 6', note = '• Time Devourer is a separate BCNM; bring 6 players and talk to the Hunts Master.' }, { title = 'Step 7', note = '• 500 unique kills gives Kupon W-RMEA, a second free REMA weapon; use Dynamis Divergence and Fay augment rerolls between hunts.' }, { title = 'Step 8', note = '• Raise ML to 50 through sieges and, once available, the Colosseum.' }, { title = 'Key NPCs', note = '• NM Hunts Master, Celennia Memorial Library (enter via Eppel-Treppel, Eastern Adoulin): progress, bounties, Elite spawns.\n• NM Hunt shop, beside the Hunts Master: Scyld purchases and milestone Kupons.\n• Greeter Moogle, Port San d\'Oria / Port Bastok / Port Windurst: Login Points shop.\n• Callisto, Grauberg [S] (-102, 538): Fay weapon augments.\n• Aurix, Ru\'Lude Gardens: Dynamis Divergence entry (Empty Hourglass).\n• Advanced Support NPC, Chocobo Circuit: 15-minute Imagery buff for the 9 crafts.\n• Synergy Engineer: 17 zones, every capital and major city.' } } },
}

return S
